SELECT * FROM check_ins
WHERE user_id = #{userId} AND check_in_date = #{date}
LIMIT 1

SELECT * FROM check_ins
WHERE user_id = #{userId}
  AND DATE_FORMAT(check_in_date, '%Y-%m') = #{yearMonth}
ORDER BY check_in_date ASC

SELECT * FROM check_ins
WHERE user_id = #{userId}
ORDER BY check_in_date DESC
LIMIT #{limit}
